from confluent_kafka import Producer
import json

producer = Producer({
    'bootstrap.servers': 'localhost:9092',
    'acks': 'all',                 # wait for all in-sync replicas
    'enable.idempotence': True,    # no duplicate writes on retry
    'compression.type': 'lz4',
    'linger.ms': 20,               # batch for throughput
})

def delivery_report(err, msg):
    if err is not None:
        print(f'Delivery failed: {err}')
    else:
        print(f'Delivered to {msg.topic()}[{msg.partition()}]@{msg.offset()}')

event = {'order_id': 'A-1009', 'amount': 49.99, 'status': 'PLACED'}

# key = order_id ensures all events for this order go to one partition (ordered)
producer.produce(
    topic='orders',
    key=event['order_id'],
    value=json.dumps(event),
    callback=delivery_report,
)
producer.flush()
